import manifest from './image-manifest.json'

/**
 * Image registry. Renditions live in /public/images as `<name>-<width>.webp`;
 * the manifest (generated by scripts/process-images.mjs) records the original
 * dimensions, available widths and a tiny blurred placeholder.
 */
export type ImageName = keyof typeof manifest

export interface ImageInfo {
  w: number
  h: number
  widths: number[]
  lqip: string
}

export const images = manifest as Record<ImageName, ImageInfo>

export const imageSrc = (name: ImageName, width?: number) => {
  const info = images[name]
  const w = width ? (info.widths.find((x) => x >= width) ?? info.widths.at(-1)!) : info.widths.at(-1)!
  return `/images/${name}-${w}.webp`
}

export const imageSrcSet = (name: ImageName) =>
  images[name].widths.map((w) => `/images/${name}-${w}.webp ${w}w`).join(', ')

/** A named image plus the alt text for the context it's used in. */
export interface Photo {
  src: ImageName
  alt: string
}
